import{_ as l,l as o,o as e,c as s,v as t,p as n,x as r,d,i as p,S as A}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"API 安全与 BOLA","description":"","frontmatter":{"title":"API 安全与 BOLA","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/api-security-bola.md","filePath":"cs/api-security-bola.md","lastUpdated":1789023840000}'),c={name:"cs/api-security-bola.md"};function h(u,a,_,E,P,B){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="api-安全与-bola" tabindex="-1">API 安全与 BOLA <a class="header-anchor" href="#api-安全与-bola" aria-label="Permalink to &quot;API 安全与 BOLA&quot;">​</a></h1><div class="epigraph"><p>对象级授权失败：认证过了，但改一个标识就碰到别人的资源。API 把客体直接暴露成 URL 与 JSON，授权必须每对象检查，而不是只检查已登录。</p><footer>—— 据 OWASP API Security；CWE-639 IDOR；对照[最小特权](/cs/acl-least-priv)</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/waf">WAF</a>几乎不管这个标识是不是你的。缺口是 <strong>BOLA 与 IDOR</strong>。Web 课序在此收口，下一课序网络防御。不给盗数据步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>按对象标识取资源时只验会话。缺口：每请求检查属主或能力令牌。批量接口更容易漏。</p><h3 id="查询语言接口" tabindex="-1">查询语言接口 <a class="header-anchor" href="#查询语言接口" aria-label="Permalink to &quot;查询语言接口&quot;">​</a></h3><p>标识与节点同样要授权，内省不是许可。</p><p><span class="marginnote">OWASP API1。禁止 IDOR 利用教程。IDS 下一课换到网络流量视角。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>测试：换标识、换租户。设计：不可预测标识只提高代价，不是授权。下一课 IDS/IPS。</p>',12)),(e(),n(A,null,{default:r(()=>[p(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20AUTH%5B%22%E5%B7%B2%E8%AE%A4%E8%AF%81%22%5D%20--%3E%20OBJ%5B%22%E5%AE%A2%E4%BD%93%E6%A0%87%E8%AF%86%22%5D%0A%20%20OBJ%20--%3E%20AUTHZ%5B%22%E5%B1%9E%E4%B8%BB%E6%88%96%20ACL%20%E6%A3%80%E6%9F%A5%22%5D%0A%20%20AUTHZ%20--%3E%20FAIL%5B%22%E5%8F%AA%E9%AA%8C%E7%99%BB%E5%BD%95%E5%88%99%20BOLA%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Web 单元收口：从 XSS 到客体授权。网络防御单元从流量检测起，假定应用仍会漏。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>零盗取教程。下一课序 IDS/IPS。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>WAF 看不见对象属主。</li><li>BOLA：认证不等于对该客体的授权。</li><li>每对象检查；随机标识不是 ACL。</li><li>下一课序：IDS/IPS。</li><li>出处：OWASP API Security；CWE-639。</li></ul>',8))])}const b=l(c,[["render",h]]);export{S as __pageData,b as default};
